WITH enriched AS (SELECT *, SUM(sqft) OVER (PARTITION BY region ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, ROW_NUMBER() OVER (PARTITION BY region ORDER BY sqft DESC, id ASC) AS event_seq, LAST_VALUE(region) IGNORE NULLS OVER w_grp AS last_known_region, LAG(sqft, 1) OVER (PARTITION BY city, region ORDER BY sqft ASC, id ASC) AS prev_sqft, ROUND(sqft / SUM(sqft) OVER (PARTITION BY region), 4) AS sqft_share FROM stores WINDOW w_grp AS (PARTITION BY region ORDER BY sqft ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), latest_match AS (SELECT s.*, x.inventory_quantity, x.inventory_last_restock FROM enriched s LEFT JOIN LATERAL (SELECT c.quantity AS inventory_quantity, c.last_restock AS inventory_last_restock FROM inventory c WHERE c.store_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) x ON TRUE), filtered AS (SELECT *, LAST_DAY(opened_date) AS opened_date_month_end FROM latest_match WHERE opened_date >= TO_DATE('2023-10-31') AND region IS NOT NULL), scored AS (SELECT *, PERCENT_RANK() OVER (ORDER BY sqft DESC) AS sqft_percent_rank, ROW_NUMBER() OVER (ORDER BY event_seq ASC, id ASC) AS event_seq_2, SUM(sqft_share) OVER (PARTITION BY city ORDER BY running_sqft ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sqft_share FROM filtered), totals AS (SELECT city, CASE WHEN sqft_share >= 0.66 THEN 'PREMIUM' ELSE 'STANDARD' END AS sqft_share_tier, ROUND(AVG(event_seq), 2) AS avg_event_seq, COUNT(DISTINCT id) AS distinct_ids, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN region = 'North' THEN 1 END), 0), 2) AS sqft_per_north, SUM(CASE WHEN region = 'East' THEN inventory_quantity ELSE 0 END) AS east_inventory_quantity, SIZE(COLLECT_SET(region)) AS num_regions FROM scored GROUP BY city, sqft_share_tier) SELECT city, sqft_share_tier, avg_event_seq, distinct_ids, sqft_per_north, east_inventory_quantity, num_regions, CASE WHEN city RLIKE '^(Berlin|New York)$' THEN 'PRIORITY' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS city_zone FROM totals ORDER BY city DESC NULLS FIRST, num_regions ASC
